import{z as i,x as A,o as r,c as p,q as n,j as s,D as e,d as E,s as B,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"查询计划","description":"","frontmatter":{"title":"查询计划","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/query-plan.md","filePath":"cs/query-plan.md","lastUpdated":1791413859000}'),d={name:"cs/query-plan.md"};function c(m,a,h,S,u,F){const l=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="查询计划" tabindex="-1">查询计划 <a class="header-anchor" href="#查询计划" aria-label="Permalink to &quot;查询计划&quot;">​</a></h1><div class="epigraph"><p>逻辑树说结果是什么；物理计划说用哪些算子、何种顺序、每一步读哪份文件。</p><footer>—— 据 Selinger et al., Access Path Selection in a Relational Database Management System, SIGMOD 1979 整理</footer></div><p><a href="/cs/sort-merge-join">上一课</a>交出三种连接的 I/O 形状。本课不重做哈希表。缺口是：一条 SQL 对应许多物理树——扫描还是索引、连接谁先谁后、谓词在哪一层求值。计划是这棵被选中的算子树，后课才谈如何估代价并在候选中挑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>声明语言允许优化器改写，但执行器只跑一棵具体的树：<span class="marginnote">术语翻译：逻辑树回答「结果由哪些关系经什么代数运算得到」，物理计划回答「每个运算用哪种算法、按什么顺序跑」——前者像菜谱里的「先炒后炖」，后者是「用多大火、使哪口锅」。</span>叶是访问路径（堆扫描、索引扫描），内节点是物理算子（过滤、投影、某一种连接、排序、聚集）。缺口不是代数等价，而是<strong>把逻辑树特化成可执行的管道</strong>，并记住管道上的顺序与物化点。</p><p>没有这棵树，后课的代价没有对象，改写也没有「改完之后跑什么」。本课不引入动态规划搜连接顺序的全部细节，只锁定计划 = 带物理选择的算子树。</p><p><span class="marginnote">System R 的 Selinger 路径选择把「访问路径」与「连接顺序」一起搜。本课先命名计划，数字模型下一课才写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从逻辑代数出发，为每个逻辑运算标注物理算法与预计的输入描述（有序否、有无索引）。<span class="marginnote">可以把它想象成流水线与仓储：流水线算子像传送带，上游出一批、下游加工一批，内存里只留少量在途数据；物化点像中转仓库，必须等整批货到齐（比如排序）才能发给下一站。</span>流水线：父算子按需向子算子要下一批元组，中间结果不必全落地。物化：排序、哈希建表、某些聚集必须把输入收齐。迭代器模型（open / next / close）是执行器的接口，不是另一种查询语言。</p>',9)),(r(),s(o,null,{default:e(()=>[B(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E9%80%BB%E8%BE%91%E4%BB%A3%E6%95%B0%E6%A0%91%22%5D%20--%3E%20PHYS%5B%22%E7%89%A9%E7%90%86%E8%AE%A1%E5%88%92%E6%A0%91%22%5D%0A%20%20PHYS%20--%3E%20SCAN%5B%22%E8%AE%BF%E9%97%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PHYS%20--%3E%20PIPE%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%20%2F%20%E7%89%A9%E5%8C%96%22%5D%0A%20%20PHYS%20--%3E%20COST%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%BB%A3%E4%BB%B7%E4%BC%B0%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("计划决定局部性："),t("a",{href:"/cs/buffer-dirty"},"缓冲"),E("里的页是否被反复扫，取决于外层循环是表还是驱动索引。物化点把内存峰值从「整棵树同时活」改成「当前算子的工作区」。同一逻辑连接，左深树与bushy树的流水线形状不同，System R 常限左深以缩小搜索空间——这是搜索策略，不是语义。")],-1)),(r(),s(o,null,{default:e(()=>[B(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22SQL%EF%BC%9A%E5%8F%AA%E6%8F%8F%E8%BF%B0%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20L%5B%22%E9%80%BB%E8%BE%91%E6%A0%91%EF%BC%9A%E8%BF%9E%E6%8E%A5%20%2F%20%E8%BF%87%E6%BB%A4%20%2F%20%E6%8A%95%E5%BD%B1%22%5D%0A%20%20L%20--%3E%20P%7B%22%E7%89%A9%E7%90%86%E7%89%B9%E5%8C%96%22%7D%0A%20%20P%20--%3E%20S%5B%22%E5%A0%86%E6%89%AB%E6%8F%8F%20%E6%88%96%20%E7%B4%A2%E5%BC%95%E6%89%AB%E6%8F%8F%22%5D%0A%20%20P%20--%3E%20J%5B%22%E5%93%88%E5%B8%8C%20%2F%20%E5%BD%92%E5%B9%B6%20%2F%20%E5%B5%8C%E5%A5%97%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20S%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%E5%8F%AA%E8%B7%91%E8%BF%99%E4%B8%80%E6%A3%B5%E6%A0%91%22%5D%0A%20%20J%20--%3E%20EX%0A%20%20EX%20--%3E%20PIPE%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%EF%BC%9A%E9%80%90%E6%89%B9%E5%90%91%E4%B8%8A%E6%8E%A8%22%5D%0A%20%20EX%20--%3E%20MAT%5B%22%E7%89%A9%E5%8C%96%E7%82%B9%EF%BC%9A%E6%8E%92%E5%BA%8F%E9%9C%80%E6%94%B6%E9%BD%90%E8%BE%93%E5%85%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">初学者容易以为 SQL 里写什么顺序、机器就按什么顺序执行；实际上跑的是优化器选出的计划树——WHERE 写在最后也可能被下推提前求值，「语句顺序 = 执行顺序」并不成立。</span></p><p>解释执行按迭代器拉元组；代码生成把计划编成循环，本课不选哪一种，只要求：执行的对象是计划，不是 SQL 字符串。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>EXPLAIN</code> 输出当理论。也不处理自适应计划、运行时改树。并行与分布式计划（exchange、两阶段提交侧的查询）尚未进场；本课默认单机、单线程管道，后课事务另加锁与版本。</p><p>准备（prepare）可以把计划缓存起来，绑定变量改变的是常量，不是树的形状——那是实现加速，语义仍是这一棵。后课默认：谈到优化，改的是计划树；代价是树上的数；改写是逻辑层到逻辑层，再落到物理。</p><p>计划缓存使同一棵树服务许多绑定变量；正确性仍是那棵树的指称，不是「这次碰巧走了索引」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连接算法已在；本课把它们装进一棵可执行的物理树。</li><li>访问路径、流水线与物化点是计划的组成部分。</li><li>代价数字与搜谁最优，是后课缺口。</li><li>出处：Selinger et al., SIGMOD 1979；Garcia-Molina, Ullman and Widom。</li></ul>',8))])}const _=i(d,[["render",c]]);export{P as __pageData,_ as default};
